WoWFA_Data[1513] = "یک beast را می‌ترساند و باعث می‌شود تا حداکثر 20 ثانیه از ترس فرار کند. آسیب واردشده ممکن است اثر را قطع کند. در هر زمان فقط یک beast می‌تواند تحت Fear باشد."
WoWFA_En[5116] = "Dazes the target, slowing movement speed by $s1% for $d.$?a137015[\n\nCobra Shot will increase the duration of Concussive Shot on the target by ${$56641m3/10}.1 sec.]?a137016[\n\nSteady Shot will increase the duration of Concussive Shot on the target by ${$56641m3/10}.1 sec.][]"
WoWFA_Data[5116] = "هدف را دچار Daze می‌کند و سرعت حرکت را به‌اندازهٔ 50% برای 6 ثانیه کاهش می‌دهد.$?a137015[\n\nCobra Shot مدت Concussive Shot را روی هدف به‌اندازهٔ 3 ثانیه افزایش می‌دهد.]?a137016[\n\nSteady Shot مدت Concussive Shot را روی هدف به‌اندازهٔ 3 ثانیه افزایش می‌دهد.][]"
WoWFA_En[19434] = "A powerful aimed shot that deals $s1 Physical damage."
WoWFA_Data[19434] = "شلیکی قدرتمند و نشانه‌گیری‌شده که $s1 آسیب Physical وارد می‌کند."
WoWFA_En[19574] = "Sends you and your pet into a rage, instantly dealing $344572s1 Physical damage to its target, and increasing all damage you both deal by $s1% for $d. Removes all crowd control effects from your pet. $?s193532[\n\nActivating Bestial Wrath grants $s2 $Lcharge:charges; of Barbed Shot.][]$?s231548&!s193532[.][]"
WoWFA_Data[19574] = "شما و پتتان را به خشم می‌کشاند که بلافاصله به هدفش $344572s1 آسیب Physical وارد می‌کند و تمام آسیبی که هر دوی شما وارد می‌کنید را به‌اندازهٔ 20% برای 15 ثانیه افزایش می‌دهد. تمام اثرات کنترل جمعیت را از پت شما حذف می‌کند. $?s193532[\n\nفعال کردن Bestial Wrath، $s2 شارژ Barbed Shot اعطا می‌کند.][]$?s231548&!s193532[.][]"
WoWFA_En[19577] = "Commands your pet to intimidate the target stunning your target for $24394d$?a1258509[ and nearby enemies for ${$1258508d}.1 sec][]."
WoWFA_Data[19577] = "به پت شما فرمان می‌دهد که هدف را بترساند و هدف شما را برای 5 ثانیه$?a1258509[ و دشمنان نزدیک را برای 1 ثانیه][] استان می‌کند."
WoWFA_Data[19801] = "1 Enrage و 1 Magic را از یک هدف دشمن حذف می‌کند."
WoWFA_En[34026] = "Give the command to kill, causing your pet to charge your target and savagely deal $83381s1 Physical damage to the enemy."
WoWFA_Data[34026] = "فرمان کشتن را صادر می‌کنید و پت شما به سمت هدف شما حمله می‌کند و $83381s1 آسیب Physical را به‌شکل وحشیانه به دشمن وارد می‌کند."
WoWFA_Data[34477] = "تمام تهدیدی که ایجاد می‌کنید را به عضو پارتی یا ریدِ انتخاب‌شده منحرف می‌کند؛ با حملهٔ بعدی شما در طول 30 ثانیه شروع می‌شود و برای 8 ثانیه دوام دارد."
WoWFA_En[53351] = "You attempt to finish off a wounded target, dealing $s1 Physical damage. Only usable on enemies with less than $s2% health."
WoWFA_Data[53351] = "تلاش می‌کنید هدفی زخمی را از پای درآورید و $s1 آسیب Physical وارد می‌کنید. فقط روی دشمنانی با سلامتی کمتر از 20% قابل استفاده است."
WoWFA_Data[53480] = "به پت شما فرمان می‌دهد از یک هدف دوستانه محافظت کند و آسیب دریافتی آن را به‌اندازهٔ 15% کاهش می‌دهد، اما 50% از تمام آسیب دریافتی آن هدف به پت شما منتقل می‌شود.\n\nبرای 10 ثانیه دوام دارد یا تا زمانی که سلامتی پت شما کمتر از 25% شود."
WoWFA_Data[109215] = "Disengage همچنین شما را از تمام اثرات مختل‌کنندهٔ حرکت آزاد می‌کند و سرعت حرکت شما را به‌اندازهٔ 50% برای 4 ثانیه افزایش می‌دهد."
WoWFA_En[109248] = "Fires a magical projectile, tethering the enemy and any other enemies within $s2 yds for $d, stunning them for $117526d if they move more than $s2 yds from the arrow.$?s321468[\n\nTargets stunned by Binding Shot deal $321469s1% less damage to you for $321469d after the effect ends.][]"
WoWFA_Data[109248] = "یک پرتابهٔ جادویی شلیک می‌کند که دشمن و هر دشمن دیگری در فاصلهٔ 5 یارد را برای 10 ثانیه به هم زنجیر می‌کند و برای 3 ثانیه آن‌ها را استان می‌کند اگر بیش از 5 یارد از تیر دور شوند.$?s321468[\n\nهدف‌هایی که با Binding Shot استان می‌شوند، به‌اندازهٔ 10% آسیب کمتری برای 8 ثانیه پس از پایان اثر به شما وارد می‌کنند.][]"
WoWFA_En[115939] = "After you Wild Thrash, your pet's melee attacks also strike all nearby enemies for $s1% of the damage$?s378207[ and Kill Command strikes all nearby enemies for $s1% of the damage][] for the next ${$s2/1000}.1 sec. Deals reduced damage beyond $118459s2 targets."
WoWFA_Data[115939] = "پس از Wild Thrash، حملات نزدیک پت شما نیز به همهٔ دشمنان نزدیک به‌اندازهٔ 70% آسیب$?s378207[ وارد می‌کنند و Kill Command نیز به همهٔ دشمنان نزدیک به‌اندازهٔ 70% آسیب وارد می‌کند][]؛ این اثر طی 10 ثانیهٔ بعد فعال است. آسیب پس از 8 هدف کاهش می‌یابد."
WoWFA_Data[120679] = "آسیب اثرات خونریزی شما 4% شانس دارد یک جانور وحشی قدرتمند را جذب کند که برای 8 ثانیه به هدف شما حمله می‌کند."
WoWFA_Data[147362] = "کست اسپل را قطع می‌کند و برای 5 ثانیه از کست شدن هر اسپلی از آن school جلوگیری می‌کند."
WoWFA_En[186270] = "A vicious slash dealing $s1 Physical damage."
WoWFA_Data[186270] = "ضربه‌ای برنده که $s1 آسیب Physical وارد می‌کند."
WoWFA_Data[187698] = "یک تلهٔ قیر به مکان هدف پرتاب می‌کند که وقتی اولین دشمن نزدیک شود، استخر قیری به شعاع 8 یارد برای 30 ثانیه اطراف خود ایجاد می‌کند. تمام دشمنان در حالت داخل ناحیهٔ اثر، سرعت حرکتشان به‌اندازهٔ 50% کاهش می‌یابد. حداکثر 1. تله برای 1 دقیقه باقی می‌ماند."
WoWFA_Data[187707] = "کست اسپل را قطع می‌کند و برای 5 ثانیه از کست شدن هر اسپلی از آن school جلوگیری می‌کند."
WoWFA_Data[191384] = "آسیب Bite، Claw و Smack و اثربخشی توانایی‌های خاص پت شما را به‌اندازهٔ 30% افزایش می‌دهد.\n\nاثربخشی توانایی‌های غیرفعال Predator's Thirst، Endurance Training و Pathfinding پت شما را به‌اندازهٔ 50% افزایش می‌دهد."
