WoWFA_En[217200] = "Fire a shot that tears through your enemy, causing them to bleed for ${$s1*$s2} damage over $d. If Barbed Shot is reapplied, any remaining damage will be added to the new Barbed Shot.\n\n|cFFFFFFFFGenerates ${$246152s1*$246152d/$246152t1} Focus over $246152d.|r"
