WoWFA_En[1253830] = "$?c2[Precise Shots damage bonus][Tip of the Spear damage bonus] increased by $?c2[$s1][$s2]%.\n\n$?c2[Trueshot][Takedown] duration increased by $?c2[${$s3/1000}][${$s4/1000}] sec."
WoWFA_Data[1253830] = "$?c2[پاداش آسیب Precise Shots][پاداش آسیب Tip of the Spear] به‌اندازهٔ $?c2[10][4]% افزایش می‌یابد.\n\nمدت $?c2[Trueshot][Takedown] به‌اندازهٔ $?c2[2][2] ثانیه افزایش می‌یابد."
